            if (paymentAmountUpdateRequest._SplitsOption.IsSet)
            {
                writer.WritePropertyName("splits");
                JsonSerializer.Serialize(writer, paymentAmountUpdateRequest.Splits, jsonSerializerOptions);
            }
        }
    }
}
